import {openContentManager} from './content-manager.js';
import {apiRequest} from './api-client.js';
/** Admin endpoints authorize server-side; no client state grants permission. */
export async function openAdminHub({modal,toast,openStudio,openContent}){
 modal('<div class="dialog-padding admin-hub"><p class="eyebrow">AETHER / OPERATIONS</p><h2>Creator dashboard</h2><p>Publish stories, understand your audience, and manage membership offers.</p><div class="video-actions"><button class="button button-primary" id="hubContent">Content library</button><button class="button button-secondary" id="hubStudio">Upload & publish</button><button class="button button-secondary" id="hubRefresh">Refresh analytics</button><button class="button button-secondary" id="hubPlans">Subscription plans</button></div><p id="hubStatus" role="status">Loading protected analytics…</p><div id="hubAnalytics"></div><section id="hubPlanSection" hidden></section></div>','Aether administration');
 const root=document.querySelector('.admin-hub'),get=id=>root.querySelector('#'+id);get('hubStudio').onclick=()=>openStudio();get('hubContent').onclick=()=>openContent?openContent():openContentManager({modal,toast,openStudio,onBack:()=>openAdminHub({modal,toast,openStudio,openContent})});
 const refresh=async()=>{try{get('hubStatus').textContent='Updating analytics…';const data=await apiRequest('/api/admin/analytics');if(!root.isConnected)return;const area=get('hubAnalytics');area.replaceChildren();const metrics=document.createElement('div');metrics.className='analytics-metrics';for(const [label,value] of [['Active streams',data.totals.active_streams],['Active accounts',data.totals.active_accounts],['Playback starts · 24h',data.totals.starts_24h],['Active subscribers',data.totals.subscribers]]){const card=document.createElement('div'),number=document.createElement('strong'),name=document.createElement('span');number.textContent=value;name.textContent=label;card.append(number,name);metrics.append(card);}area.append(metrics);
 for(const [heading,rows,key] of [['Active sessions by title',data.watching,'streams'],['Trending · last 24 hours',data.trending,'starts']]){const section=document.createElement('section');section.className='state-panel';const h=document.createElement('h3');h.textContent=heading;section.append(h);if(!rows.length){const empty=document.createElement('p');empty.textContent='No playback activity in this window.';section.append(empty);}for(const row of rows){const line=document.createElement('div');line.className='analytics-row';const name=document.createElement('span'),value=document.createElement('strong');name.textContent=row.name;value.textContent=row[key]+(key==='streams'?' streams':' starts');line.append(name,value);section.append(line);}area.append(section);}get('hubStatus').textContent='Updated '+new Date(data.asOf).toLocaleTimeString()+'. '+data.definition;}catch(e){get('hubStatus').textContent=e.message;}};
 get('hubRefresh').onclick=refresh;
 get('hubPlans').onclick=async()=>{try{const [plans,billing]=await Promise.all([apiRequest('/api/admin/plans'),apiRequest('/api/billing')]);if(!root.isConnected)return;const section=get('hubPlanSection');section.hidden=false;section.innerHTML='<h3>Membership offers</h3><p>Changes create a new monthly Stripe price for new subscribers. Existing members retain their price and stream limit.</p><div id="adminPlanList"></div><form class="admin-form" id="planForm"><label>Existing plan or new plan<select name="existing" id="planExisting"><option value="">Create a plan</option></select></label><label>Plan ID<input name="id" pattern="[a-z][a-z0-9_-]{1,39}" required placeholder="e.g. weekend"></label><label>Display name<input name="name" required maxlength="80"></label><label>Monthly price (major currency units)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Currency<select name="currency"><option value="inr">INR</option><option value="usd">USD</option><option value="eur">EUR</option><option value="gbp">GBP</option></select></label><label>Simultaneous streams<select name="streams"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><p class="notice">Saving creates a Stripe product and immutable recurring price. Existing subscriptions are never repriced.</p><button class="button button-primary" type="submit">Save new-user price</button><p id="planSaveStatus" role="status"></p></form>';
 const picker=get('planExisting'),form=get('planForm');for(const plan of plans){picker.add(new Option(plan.name+' · '+plan.stream_limit+' streams',plan.id));const line=document.createElement('p');line.textContent=plan.name+' · '+plan.stream_limit+' streams · '+plan.versions+' price versions';get('adminPlanList').append(line);}picker.onchange=()=>{const selected=plans.find(p=>p.id===picker.value),price=billing.plans.find(p=>p.id===picker.value);form.elements.id.value=selected?.id||'';form.elements.id.readOnly=!!selected;form.elements.name.value=selected?.name||'';form.elements.streams.value=selected?.stream_limit||1;form.elements.amount.value=price?price.amount/100:'';form.elements.currency.value=price?.currency||'inr';};let requestId=crypto.randomUUID(),pendingBody=null;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;try{const values=Object.fromEntries(new FormData(form));const body={id:values.id,name:values.name,amount:Math.round(Number(values.amount)*100),currency:values.currency.toLowerCase(),streams:Number(values.streams),requestId};const hash=JSON.stringify({...body,requestId:null});if(pendingBody&&pendingBody!==hash)throw new Error('Retry the same values first, or reopen the dashboard to start a new request.');pendingBody=hash;get('planSaveStatus').textContent='Creating new-user price in Stripe…';await apiRequest('/api/admin/plans',{method:'POST',body:JSON.stringify(body)});requestId=crypto.randomUUID();pendingBody=null;get('planSaveStatus').textContent='Saved. Existing subscribers keep their original price. Refresh this section to view the updated offer.';toast('Subscription offer saved');}catch(error){get('planSaveStatus').textContent=error.message;}finally{button.disabled=false;}};section.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){get('hubStatus').textContent=e.message;}};
 await refresh();const poll=()=>setTimeout(async()=>{if(!root.isConnected)return;if(!document.hidden)await refresh();poll();},30000);poll();
}
